COMMON_SRC = '"""Общее для всех экспериментов: загрузка, чистка, val-split, оценка."""\nimport re\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.metrics import average_precision_score, f1_score, precision_score, recall_score\nfrom sklearn.model_selection import train_test_split\n\nTEST_PATH = "computers_gs.json"\nTRAIN_PATH = "computers_train/computers_train_{}.json.gz"\nSPLITS_DIR = Path("splits")\nPRED_DIR = Path("predictions")\nSEED = 42\n\n# хвосты с названием магазина/страницы, найденные в EDA. По умолчанию НЕ удаляем: в экспериментах\n# (REPORT_classic.md) их удаление ухудшило F1 на ~3 п. — название магазина оказалось полезным сигналом.\nSHOP_TAIL = re.compile(r"(\\s*[|▷»].*$)|(\\s*-\\s*black friday 2017)|(\\b\\S+\\.com\\b)|(\\s-us\\b)")\n\n\ndef clean(s, mode="light"):\n    """mode: "none" — только нижний регистр; "light" — + убираем "..."@en и \'null\';\n    "full" — + удаляем хвосты с названием магазина."""\n    if not isinstance(s, str):\n        return ""\n    if mode == "none":\n        return s.lower()\n    s = re.sub(r\'"@\\w+\', " ", s).replace(\'"\', " ").lower()\n    s = re.sub(r"\\bnull\\b", " ", s)\n    if mode == "full":\n        s = SHOP_TAIL.sub(" ", s)\n    return re.sub(r"\\s+", " ", s).strip()\n\n\ndef load(path, clean_mode="light"):\n    fn = lambda s: clean(s, clean_mode)\n    df = pd.read_json(path, lines=True, dtype={"label": int})\n    for col in ["title", "description", "brand"]:\n        for side in ["left", "right"]:\n            df[f"{col}_{side}"] = df[f"{col}_{side}"].map(fn)\n    return df\n\n\ndef load_split(size, clean_mode="light"):\n    """train/val из train_{size} (фиксированный стратифицированный split 80/20, id сохраняются в splits/) + test."""\n    full = load(TRAIN_PATH.format(size), clean_mode)\n    split_file = SPLITS_DIR / f"val_ids_{size}.txt"\n    if split_file.exists():\n        val_ids = set(split_file.read_text().split())\n    else:\n        _, val = train_test_split(full, test_size=0.2, stratify=full.label, random_state=SEED)\n        SPLITS_DIR.mkdir(exist_ok=True)\n        split_file.write_text("\\n".join(val.pair_id))\n        val_ids = set(val.pair_id)\n    is_val = full.pair_id.isin(val_ids)\n    return full[~is_val].reset_index(drop=True), full[is_val].reset_index(drop=True), load(TEST_PATH, clean_mode)\n\n\ndef hard_mask(df):\n    """«Трудные» пары: негативы с похожими заголовками и позитивы с непохожими (как в test)."""\n    vec = TfidfVectorizer(token_pattern=r"[a-z0-9]+", sublinear_tf=True).fit(pd.concat([df.title_left, df.title_right]))\n    cos = np.asarray(vec.transform(df.title_left).multiply(vec.transform(df.title_right)).sum(1)).ravel()\n    return ((df.label == 0) & (cos >= 0.5)) | ((df.label == 1) & (cos < 0.3))\n\n\ndef best_threshold(y, scores):\n    grid = np.unique(np.quantile(scores, np.linspace(0, 1, 201)))\n    f1s = [f1_score(y, scores >= t, zero_division=0) for t in grid]\n    return float(grid[int(np.argmax(f1s))])\n\n\ndef metrics(y, scores, t):\n    pred = scores >= t\n    return {"F1": f1_score(y, pred, zero_division=0), "P": precision_score(y, pred, zero_division=0),\n            "R": recall_score(y, pred, zero_division=0), "PR_AUC": average_precision_score(y, scores)}\n\n\ndef bootstrap_f1(y, pred, n=1000, seed=SEED):\n    y, pred = np.asarray(y), np.asarray(pred)\n    rng = np.random.default_rng(seed)\n    idx = rng.integers(0, len(y), size=(n, len(y)))\n    tp = ((pred[idx] == 1) & (y[idx] == 1)).sum(1)\n    f1 = 2 * tp / (pred[idx].sum(1) + y[idx].sum(1))\n    return np.percentile(f1, [2.5, 97.5])\n\n\ndef paired_compare(y, pred_a, pred_b, n=1000, seed=SEED):\n    """Сравнение моделей A и B на одном test: ΔF1 = F1(B) − F1(A) с 95% ДИ (paired bootstrap)\n    и p-value теста Макнемара по парам, где модели ошиблись по-разному."""\n    from scipy.stats import binomtest\n\n    y, a, b = (np.asarray(v).astype(int) for v in (y, pred_a, pred_b))\n    idx = np.random.default_rng(seed).integers(0, len(y), size=(n, len(y)))\n\n    def f1(p):\n        tp = ((p[idx] == 1) & (y[idx] == 1)).sum(1)\n        return 2 * tp / (p[idx].sum(1) + y[idx].sum(1))\n\n    delta = f1(b) - f1(a)\n    only_a = int(((a == y) & (b != y)).sum())\n    only_b = int(((b == y) & (a != y)).sum())\n    p = binomtest(only_a, only_a + only_b).pvalue if only_a + only_b else 1.0\n    return {"dF1": float(f1_score(y, b) - f1_score(y, a)), "dF1_lo": float(np.percentile(delta, 2.5)),\n            "dF1_hi": float(np.percentile(delta, 97.5)), "mcnemar_p": float(p)}\n\n\ndef evaluate(name, size, val, val_scores, test, test_scores, save=True):\n    """Порог выбираем по F1 на val, применяем к test. Сохраняем предсказания для будущих парных сравнений."""\n    t = best_threshold(val.label, val_scores)\n    hard = hard_mask(val)\n    res = {"model": name, "train": size, "threshold": t,\n           **{f"val_{k}": v for k, v in metrics(val.label, val_scores, t).items()},\n           "val_hard_F1": metrics(val.label[hard], val_scores[hard], t)["F1"],\n           **{f"test_{k}": v for k, v in metrics(test.label, test_scores, t).items()}}\n    lo, hi = bootstrap_f1(test.label, test_scores >= t)\n    res["test_F1_CI"] = f"[{lo:.3f}, {hi:.3f}]"\n\n    res["test_pred"] = (test_scores >= t).astype(int)\n    if not save:\n        return res\n    PRED_DIR.mkdir(exist_ok=True)\n    slug = re.sub(r"\\W+", "_", name).strip("_").lower()\n    pd.DataFrame({"pair_id": test.pair_id, "label": test.label, "score": test_scores, "pred": (test_scores >= t).astype(int)}\n                 ).to_csv(PRED_DIR / f"{slug}__{size}__test.csv", index=False)\n    return res\n'
DL_SRC = '"""Этап 3: трансформер-кросс-энкодер для пар офферов.\n\n  [CLS] оффер A [SEP] оффер B  ->  P(дубль)\n\nТот же val-split и та же оценка, что у классики (common.evaluate): порог по val F1, bootstrap-ДИ на test.\nЛучшая эпоха выбирается по val F1. Предсказания val/test сохраняются в predictions/ для парных сравнений.\n\nПример:\n  python3 dl.py --size small --model intfloat/multilingual-e5-small --epochs 5\n"""\nimport argparse\nimport copy\nimport os\nimport random\nimport time\n\nos.environ.setdefault("HF_HUB_OFFLINE", "1")  # модели берём из локального кэша\n\nimport numpy as np\nimport pandas as pd\nimport torch\nfrom sklearn.metrics import f1_score\nfrom transformers import AutoModelForSequenceClassification, AutoTokenizer, get_linear_schedule_with_warmup\n\nfrom common import PRED_DIR, best_threshold, evaluate, load_split\n\nRESULTS = "results_dl.csv"\n\n\ndef serialize(df, side, fields, desc_words):\n    """Оффер -> текст. fields=\'title\' или \'title+desc\' (описание обрезаем до desc_words слов)."""\n    title = df[f"title_{side}"]\n    if fields == "title":\n        return title.tolist()\n    desc = df[f"description_{side}"].str.split().str[:desc_words].str.join(" ")\n    return [f"{t} [SEP] {d}" if d else t for t, d in zip(title, desc)]\n\n\nclass PairData(torch.utils.data.Dataset):\n    def __init__(self, df, args):\n        self.a = serialize(df, "left", args.fields, args.desc_words)\n        self.b = serialize(df, "right", args.fields, args.desc_words)\n        self.y = df.label.tolist()\n\n    def __len__(self):\n        return len(self.y)\n\n    def __getitem__(self, i):\n        return self.a[i], self.b[i], self.y[i]\n\n\ndef make_collate(tok, max_len, swap_prob=0.0):\n    def collate(batch):\n        a, b, y = zip(*batch)\n        if swap_prob:  # аугментация: случайно меняем офферы местами\n            a, b = zip(*[(y_, x_) if random.random() < swap_prob else (x_, y_) for x_, y_ in zip(a, b)])\n        enc = tok(list(a), list(b), truncation="longest_first", max_length=max_len, padding=True, return_tensors="pt")\n        enc["labels"] = torch.tensor(y)\n        return enc\n    return collate\n\n\n@torch.no_grad()\ndef predict(model, df, tok, args, device):\n    """P(дубль); при --tta усредняем по порядкам (A,B) и (B,A)."""\n    model.eval()\n    orders = [False, True] if args.tta else [False]\n    out = []\n    for swapped in orders:\n        data = PairData(df, args)\n        if swapped:\n            data.a, data.b = data.b, data.a\n        loader = torch.utils.data.DataLoader(data, batch_size=args.bs * 2, collate_fn=make_collate(tok, args.max_len))\n        probs = []\n        for enc in loader:\n            enc = {k: v.to(device) for k, v in enc.items() if k != "labels"}\n            with torch.autocast("cuda", dtype=torch.float16, enabled=device.type == "cuda"):\n                logits = model(**enc).logits\n            probs.append(torch.softmax(logits.float(), -1)[:, 1].cpu())\n        out.append(torch.cat(probs).numpy())\n    return np.mean(out, axis=0)\n\n\ndef main():\n    p = argparse.ArgumentParser()\n    p.add_argument("--size", default="small")\n    p.add_argument("--model", default="intfloat/multilingual-e5-small")\n    p.add_argument("--fields", default="title", choices=["title", "title+desc"])\n    p.add_argument("--desc-words", type=int, default=40)\n    p.add_argument("--max-len", type=int, default=128)\n    p.add_argument("--epochs", type=int, default=5)\n    p.add_argument("--lr", type=float, default=5e-5)\n    p.add_argument("--bs", type=int, default=32)\n    p.add_argument("--warmup", type=float, default=0.1)\n    p.add_argument("--swap-aug", type=float, default=0.5, help="вероятность поменять A и B местами при обучении")\n    p.add_argument("--tta", type=int, default=1, help="усреднять предсказания по двум порядкам пары")\n    p.add_argument("--freeze-emb", type=int, default=1,\n                   help="заморозить эмбеддинги слов (у multilingual-моделей это ~80%% параметров и памяти Adam)")\n    p.add_argument("--seed", type=int, default=0)\n    p.add_argument("--limit", type=int, default=0, help="взять первые N пар train (для быстрой отладки)")\n    p.add_argument("--tag", default="")\n    args = p.parse_args()\n\n    random.seed(args.seed), np.random.seed(args.seed), torch.manual_seed(args.seed)\n    device = torch.device("cuda" if torch.cuda.is_available() else "mps" if torch.backends.mps.is_available() else "cpu")\n    use_amp = device.type == "cuda"  # fp16 на GPU (Kaggle/Colab); на MPS не используем\n    train, val, test = load_split(args.size)\n    if args.limit:\n        train = train.sample(args.limit, random_state=args.seed)\n\n    tok = AutoTokenizer.from_pretrained(args.model)\n    model = AutoModelForSequenceClassification.from_pretrained(args.model, num_labels=2).to(device)\n    if args.freeze_emb:\n        model.get_input_embeddings().weight.requires_grad_(False)\n    loader = torch.utils.data.DataLoader(PairData(train, args), batch_size=args.bs, shuffle=True,\n                                         collate_fn=make_collate(tok, args.max_len, args.swap_aug))\n    opt = torch.optim.AdamW([p_ for p_ in model.parameters() if p_.requires_grad], lr=args.lr, weight_decay=0.01)\n    steps = len(loader) * args.epochs\n    sched = get_linear_schedule_with_warmup(opt, int(args.warmup * steps), steps)\n\n    short = args.model.split("/")[-1]\n    name = f"{short} | {args.fields} | len{args.max_len} lr{args.lr:g} ep{args.epochs}" + (f" | {args.tag}" if args.tag else "")\n    print(f"{name} | train={args.size} ({len(train)} пар) | device={device}", flush=True)\n\n    scaler = torch.amp.GradScaler("cuda", enabled=use_amp)\n    best = (-1.0, None, -1)\n    t0 = time.time()\n    for epoch in range(1, args.epochs + 1):\n        model.train()\n        losses = []\n        for i, enc in enumerate(loader):\n            enc = {k: v.to(device) for k, v in enc.items()}\n            with torch.autocast("cuda", dtype=torch.float16, enabled=use_amp):\n                loss = model(**enc).loss\n            scaler.scale(loss).backward()\n            scaler.unscale_(opt)\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            scaler.step(opt), scaler.update(), sched.step(), opt.zero_grad()\n            losses.append(loss.item())\n            if i % 50 == 0:\n                print(f"  ep{epoch} step {i}/{len(loader)} loss={np.mean(losses[-100:]):.4f} "\n                      f"[{time.time() - t0:.0f}s]", flush=True)\n        if device.type == "mps":\n            torch.mps.empty_cache()\n        va_s = predict(model, val, tok, args, device)\n        va_f1 = f1_score(val.label, va_s >= best_threshold(val.label, va_s))\n        print(f"  ep{epoch}: train loss={np.mean(losses):.4f}  val F1={va_f1:.4f}  [{time.time() - t0:.0f}s]", flush=True)\n        if va_f1 > best[0]:\n            best = (va_f1, copy.deepcopy({k: v.cpu() for k, v in model.state_dict().items()}), epoch)\n\n    model.load_state_dict(best[1])\n    va_s, te_s = predict(model, val, tok, args, device), predict(model, test, tok, args, device)\n    r = evaluate(name, args.size, val, va_s, test, te_s, save=False)\n    r.pop("test_pred")\n    r.update(best_epoch=best[2], seed=args.seed, train_minutes=round((time.time() - t0) / 60, 1),\n             hf_model=args.model, **{k: v for k, v in vars(args).items() if k not in ("size", "seed", "model")})\n    print(f"\\nИТОГ ({name}, лучшая эпоха {best[2]}): val F1={r[\'val_F1\']:.3f} | test F1={r[\'test_F1\']:.3f} "\n          f"{r[\'test_F1_CI\']} P={r[\'test_P\']:.3f} R={r[\'test_R\']:.3f} PR-AUC={r[\'test_PR_AUC\']:.3f}", flush=True)\n\n    pd.DataFrame([r]).to_csv(RESULTS, mode="a", header=not os.path.exists(RESULTS), index=False)\n    PRED_DIR.mkdir(exist_ok=True)\n    slug = f"dl__{short}__{args.fields}__{args.size}__seed{args.seed}" + (f"__{args.tag}" if args.tag else "")\n    for part, df, s in [("val", val, va_s), ("test", test, te_s)]:\n        pd.DataFrame({"pair_id": df.pair_id, "label": df.label, "score": s}).to_csv(\n            PRED_DIR / f"{slug}__{part}.csv", index=False)\n\n\nif __name__ == "__main__":\n    main()\n'
RUNS = ['--size large --model intfloat/multilingual-e5-base --lr 3e-5 --seed 0', '--size large --model intfloat/multilingual-e5-base --lr 3e-5 --seed 1', '--size large --model intfloat/multilingual-e5-base --lr 3e-5 --seed 2', '--size xlarge --model intfloat/multilingual-e5-base --lr 3e-5 --seed 0', '--size xlarge --model intfloat/multilingual-e5-base --lr 3e-5 --seed 1', '--size xlarge --model intfloat/multilingual-e5-base --lr 3e-5 --seed 2', '--size small --model intfloat/multilingual-e5-base --lr 3e-5 --seed 1', '--size small --model intfloat/multilingual-e5-base --lr 3e-5 --seed 2']

import glob, os, shlex, shutil, subprocess, sys, threading
from pathlib import Path

os.chdir("/kaggle/working")
src = Path(glob.glob("/kaggle/input/**/computers_gs.json", recursive=True)[0]).parent
print("input:", sorted(p.name for p in src.iterdir()), flush=True)
for d in ["computers_train", "splits", "logs"]:
    Path(d).mkdir(exist_ok=True)
os.symlink(src / "computers_gs.json", "computers_gs.json")
# Kaggle распаковывает .gz при загрузке датасета — поддерживаем оба варианта
gz = list(src.glob("computers_train_*.json.gz"))
for f in gz or src.glob("computers_train_*.json"):
    os.symlink(f, Path("computers_train") / f.name)
if not gz:
    COMMON_SRC = COMMON_SRC.replace("computers_train_{}.json.gz", "computers_train_{}.json")
for f in src.glob("val_ids_*.txt"):
    shutil.copy(f, "splits")
Path("common.py").write_text(COMMON_SRC)
Path("dl.py").write_text(DL_SRC)
os.environ["HF_HUB_OFFLINE"] = "0"
subprocess.run(["nvidia-smi", "-L"])

# прогоны раскладываем по GPU: каждая карта берёт свою очередь
n_gpu = max(1, int(subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True).stdout.count("GPU ")))
lock = threading.Lock()

def worker(gpu, jobs):
    for i, args in jobs:
        env = {**os.environ, "CUDA_VISIBLE_DEVICES": str(gpu)}
        with open(f"logs/run{i}.txt", "w") as log:
            p = subprocess.run([sys.executable, "dl.py", *shlex.split(args)], stdout=log, stderr=subprocess.STDOUT, env=env)
        with lock:
            print(f"\n######## run {i} (gpu {gpu}): dl.py {args} -> exit {p.returncode}", flush=True)
            print(open(f"logs/run{i}.txt").read()[-1200:], flush=True)

queues = [[(i, a) for i, a in enumerate(RUNS) if i % n_gpu == g] for g in range(n_gpu)]
threads = [threading.Thread(target=worker, args=(g, q)) for g, q in enumerate(queues)]
[t.start() for t in threads]
[t.join() for t in threads]
for p in ["computers_gs.json", *glob.glob("computers_train/*")]:
    os.remove(p)
